package com.tencent.weknora.security;
import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.stream.*;
import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.jdbc.datasource.init.ScriptUtils;import org.springframework.core.io.FileSystemResource;import org.springframework.mock.web.*;import org.springframework.web.method.HandlerMethod;import org.springframework.web.servlet.HandlerMapping;import org.sqlite.SQLiteDataSource;import static org.junit.jupiter.api.Assertions.*;
class DeniedRoleAuditCompatibilityTest {
 public static class Dummy{public void handle(){}}
 @Test void legacyMemberDenialStillInsertsWhenDedupCountFails()throws Exception{Path file=Files.createTempFile("weknora-member-denied-count-",".db");try{var source=new SQLiteDataSource();source.setUrl("jdbc:sqlite:"+file);try(var connection=source.getConnection()){ScriptUtils.executeSqlScript(connection,new FileSystemResource("../migrations/sqlite/000000_init.up.sql"));}var jdbc=new JdbcTemplate(source);var failed=new JdbcTemplate(source){@Override public <T>T queryForObject(String sql,Class<T> type,Object...args){if(sql.startsWith("SELECT COUNT(*) FROM audit_logs"))throw new org.springframework.jdbc.BadSqlGrammarException("count",sql,new java.sql.SQLException("isolated count failure"));return super.queryForObject(sql,type,args);}};var service=new TenantMemberService(failed,new AuthRepository(jdbc,new ObjectMapper()),new DataSourceTransactionManager(source));var caller=new AuthContext("caller",7,"viewer",false,null,false,Set.of(),Set.of());for(int i=0;i<2;i++)service.auditDenied(caller,"/api/v1/tenants/7/members/u","PUT","owner",true);assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM audit_logs",Integer.class));assertEquals("/api/v1/tenants/:id/members/:user_id",jdbc.queryForObject("SELECT request_path FROM audit_logs LIMIT 1",String.class));}finally{Files.deleteIfExists(file);}}
 @TestFactory Stream<DynamicTest> actualGoMiddlewareAndAuditRows()throws Exception{var json=new ObjectMapper();var fixture=json.readTree(Files.readString(Path.of("src/test/java/com/tencent/weknora/security/denied-role-golden.json")));List<DynamicTest> out=new ArrayList<>();fixture.fields().forEachRemaining(entry->out.add(DynamicTest.dynamicTest(entry.getKey(),()->run(entry.getKey(),entry.getValue(),json))));return out.stream();}
 private void run(String mode,JsonNode expected,ObjectMapper json)throws Exception{Path file=Files.createTempFile("weknora-denied-role-parity-",".db");try{var source=new SQLiteDataSource();source.setUrl("jdbc:sqlite:"+file);try(var connection=source.getConnection()){ScriptUtils.executeSqlScript(connection,new FileSystemResource("../migrations/sqlite/000000_init.up.sql"));}JdbcTemplate jdbc=new JdbcTemplate(source);JdbcTemplate probes=mode.equals("failed-count")?new JdbcTemplate(source){@Override public <T>T queryForObject(String sql,Class<T> type,Object...args){if(sql.startsWith("SELECT COUNT(*) FROM audit_logs"))throw new org.springframework.jdbc.BadSqlGrammarException("oracle failed count",sql,new java.sql.SQLException("isolated count failure"));return super.queryForObject(sql,type,args);}}:jdbc;var repository=new AuthRepository(jdbc,json);var audit=new DeniedRoleAuditService(probes,repository,new DataSourceTransactionManager(source));var guard=new NativeRoleGuard(audit,json);var handler=new HandlerMethod(new Dummy(),Dummy.class.getMethod("handle"));List<Map<String,Object>> responses=new ArrayList<>();
  int n=expected.path("responses").size();for(int i=1;i<=n;i++){if(i==2&&mode.equals("expired-window"))jdbc.update("UPDATE audit_logs SET created_at=?",repository.timestampParameter(Instant.now().minusSeconds(61)));String actor=i==2&&mode.equals("different-actor")?"other":"caller";long tenant=i==2&&mode.equals("different-tenant")?8:7;AuthContext auth=new AuthContext(actor,tenant,"viewer",mode.equals("system-admin-not-owner")||mode.equals("admin-system-bypass"),mode.equals("api-key")?1L:null,false,Set.of(),Set.of(),mode.equals("cross-superuser"),!mode.equals("rbac-disabled"));String method=i==2&&mode.equals("different-method-dedup")?"DELETE":"POST";var request=new MockHttpServletRequest(method,"/api/v1/tenants/7/invitations/"+i);request.setAttribute(CurrentAuth.ATTRIBUTE,auth);request.setAttribute(HandlerMapping.BEST_MATCHING_PATTERN_ATTRIBUTE,mode.equals("admin-system-bypass")?"/api/v1/models/{id}":"/api/v1/tenants/{tenantId}/invitations/{invId}");if(mode.equals("admin-system-bypass"))request.setMethod("PUT");var response=new MockHttpServletResponse();if(guard.preHandle(request,response,handler))json.writeValue(response.getOutputStream(),Map.of("ok",true));responses.add(Map.of("status",response.getStatus(),"body",json.readTree(response.getContentAsByteArray())));}
  List<Map<String,Object>> rows=new ArrayList<>();for(var row:jdbc.queryForList("SELECT tenant_id,actor_user_id,actor_role,action,request_path,request_method,outcome,details FROM audit_logs ORDER BY id")){row.put("details",json.readTree(row.get("details").toString()));rows.add(row);}assertEquals(expected,json.readTree(json.writeValueAsBytes(Map.of("responses",responses,"audits",rows))));
 }finally{Files.deleteIfExists(file);}}
}
